import { describe, it, expect } from '@jest/globals';
import { prisma } from '@teaching-engine/database';

describe('Debug Mock', () => {
  it('should check what prisma is', () => {
    console.log('prisma:', prisma);
    console.log('prisma.curriculumExpectation:', prisma.curriculumExpectation);
    console.log('prisma.curriculumExpectation.create:', prisma.curriculumExpectation.create);
    
    expect(prisma).toBeDefined();
    expect(prisma.curriculumExpectation).toBeDefined();
    expect(prisma.curriculumExpectation.create).toBeDefined();
  });
  
  it('should check mock function', () => {
    console.log('Is mock function?', jest.isMockFunction(prisma.curriculumExpectation.create));
    console.log('Mock implementation:', (prisma.curriculumExpectation.create as any).getMockImplementation);
  });
});